import{_ as t,a0 as o,w as d,s as r,ao as l,I as e,x as a,a1 as i,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"一起来学习 Lisp 编程语言吧！ | LCTT x X-CMD","titleTemplate":false,"description":"一起来学习 Lisp 编程语言吧！ | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一起来学习 Lisp 编程语言吧！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一起来学习 Lisp 编程语言吧！ | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20210503 Learn the Lisp programming language in 2021","title":"一起来学习 Lisp 编程语言吧！","tag":"202206","desc":""},"relativePath":"202206/20210503 Learn the Lisp programming language in 2021.md","filePath":"[post].md"}'),g={name:"202206/20210503 Learn the Lisp programming language in 2021.md"};function h(c,s,u,k,b,f){const n=o("Link");return d(),r("div",null,[s[40]||(s[40]=l('<h1 id="一起来学习-lisp-编程语言吧" tabindex="-1">一起来学习 Lisp 编程语言吧！ <a class="header-anchor" href="#一起来学习-lisp-编程语言吧" aria-label="Permalink to “一起来学习 Lisp 编程语言吧！”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/24/124147v0loy4e3y0hneih8.jpg" alt=""></p><blockquote><p>许多大型代码库中都有 Lisp 代码的身影，因此，熟悉一下这门语言是一个明智之举。</p></blockquote><p>早在 1958 年，Lisp 就被发明出来了，它是世界上第二古老的计算机编程语言（LCTT 译注：最古老的编程语言是 Fortran，诞生于 1957 年）。它有许多现代的衍生品，包括 Common Lisp、Emacs Lisp（Elisp）、Clojure、Racket、Scheme、Fennel 和 GNU Guile 等。</p><p>那些喜欢思考编程语言的设计的人，往往都喜欢 Lisp，因为它的语法和数据有着相同的结构：Lisp 代码实际上是<ruby>一个列表的列表<rt>a list of lists</rt></ruby>，它的名字其实是 “<ruby>列表处理<rt>LISt Processing</rt></ruby>” 的简写。而那些喜欢思考编程语言的美学的人，往往都讨厌 Lisp，因为它经常使用括号来定义范围；事实上，编程界也有一个广为流传的笑话：Lisp 代表的其实是 <ruby>“大量烦人的多余括号”<rt>Lots of Irritating Superfluous Parentheses</rt></ruby>。</p><p>不管你是喜欢还是讨厌 Lisp 的设计哲学，你都不得不承认，它都是一门有趣的语言，过去如此，现在亦然（这得归功于现代方言 Clojure 和 Guile）。你可能会惊讶于在任何特定行业的大代码库中潜伏着多少 Lisp 代码，因此，现在开始学习 Lisp，至少熟悉一下它，不失为一个好主意。</p><h3 id="安装-lisp" tabindex="-1">安装 Lisp <a class="header-anchor" href="#安装-lisp" aria-label="Permalink to “安装 Lisp”">​</a></h3>',7)),e("p",null,[s[3]||(s[3]=a("Lisp 有很多不同的实现。比较流行的开源版本有 ",-1)),i(n,{href:"http://sbcl.org"},{default:p(()=>[...s[0]||(s[0]=[a("SBCL",-1)])]),_:1}),s[4]||(s[4]=a("、",-1)),i(n,{href:"http://clisp.org"},{default:p(()=>[...s[1]||(s[1]=[a("GNU Lisp",-1)])]),_:1}),s[5]||(s[5]=a(" 和 ",-1)),i(n,{href:"https://www.gnu.org/software/gcl/"},{default:p(()=>[...s[2]||(s[2]=[a("GNU Common Lisp",-1)])]),_:1}),s[6]||(s[6]=a("（GCL）。你可以使用发行版的包管理器安装它们中的任意一个，在本文中，我是用的是 ",-1)),s[7]||(s[7]=e("code",null,"clisp",-1)),s[8]||(s[8]=a("（LCTT 译注：也就是 GNU Lisp，一种 ANSI Common Lisp 的实现）。",-1))]),s[41]||(s[41]=l('<p>以下是在不同的 Linux 发行版中安装 <code>clisp</code> 的步骤。</p><p>在 Fedora Linux 上，使用 <code>dnf</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install clisp</span></span></code></pre></div><p>在 Debian 上，使用 <code>apt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install clisp</span></span></code></pre></div>',5)),e("p",null,[s[11]||(s[11]=a("在 macOS 上，使用 ",-1)),i(n,{href:"https://opensource.com/article/20/11/macports"},{default:p(()=>[...s[9]||(s[9]=[a("MacPorts",-1)])]),_:1}),s[12]||(s[12]=a(" 或者 ",-1)),i(n,{href:"https://opensource.com/article/20/6/homebrew-linux"},{default:p(()=>[...s[10]||(s[10]=[a("Homebrew",-1)])]),_:1}),s[13]||(s[13]=a("：",-1))]),s[42]||(s[42]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 使用 MacPorts</span></span>
<span class="line"><span>$ sudo port install clisp</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 使用 Homebrew</span></span>
<span class="line"><span>$ brew install clisp</span></span></code></pre></div>`,1)),e("p",null,[s[16]||(s[16]=a("在 Windows 上，你可以使用 ",-1)),i(n,{href:"https://cygwin.fandom.com/wiki/Clisp"},{default:p(()=>[...s[14]||(s[14]=[a("clisp on Cygwin",-1)])]),_:1}),s[17]||(s[17]=a(" 或者从 ",-1)),i(n,{href:"http://mirror.lagoon.nc/gnu/gcl/binaries/stable"},{default:p(()=>[...s[15]||(s[15]=[a("gnu.org/software/gcl",-1)])]),_:1}),s[18]||(s[18]=a(" 上下载 GCL 的二进制文件。",-1))]),s[43]||(s[43]=l(`<p>虽然我使用 <code>clisp</code> 命令来运行 Lisp 代码，但是本文中涉及到的大多数语法规则，对任何 Lisp 实现都是适用的。如果你选择使用一个不同的 Lisp 实现，除了用来运行 Lisp 代码的命令会和我不一样外（比如，你可能要用 <code>gcl</code> 或 <code>sbcl</code> 而不是 <code>clisp</code>），其它的所有东西都是相同的。</p><h3 id="列表处理" tabindex="-1">列表处理 <a class="header-anchor" href="#列表处理" aria-label="Permalink to “列表处理”">​</a></h3><p>Lisp 源代码的基本单元是 “<ruby>表达式<rt>expression</rt></ruby>”，它在形式上是一个列表。举个例子，下面就是一个列表，它由一个操作符（<code>+</code>）和两个整数（<code>1</code> 和 <code>2</code>）组成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(+ 1 2)</span></span></code></pre></div><p>同时，它也是一个 Lisp 表达式，内容是一个符号（<code>+</code>，会被解析成一个加法函数）和它的两个参数（<code>1</code> 和 <code>2</code>）。你可以在 Common Lisp 的交互式环境（即 REPL）中运行该表达式和其它表达式。如果你熟悉 Python 的 IDLE，那么你应该会对 Lisp 的 REPL 感到亲切。（LCTT 译注：REPL 的全称是 “Read-Eval-Print Loop”，意思是 “‘读取-求值-输出’循环”，这个名字很好地描述了它的工作过程。）</p><p>要进入到 REPL 中，只需运行 Common Lisp 即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ clisp</span></span>
<span class="line"><span>[1]&gt;</span></span></code></pre></div><p>在 REPL 提示符中，尝试输入一些表达式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[1]&gt; (+ 1 2)</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>[2]&gt; (- 1 2)</span></span>
<span class="line"><span>-1</span></span>
<span class="line"><span>[3]&gt; (- 2 1)</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>[4]&gt; (+ 2 3 4)</span></span>
<span class="line"><span>9</span></span></code></pre></div><h3 id="函数" tabindex="-1">函数 <a class="header-anchor" href="#函数" aria-label="Permalink to “函数”">​</a></h3><p>在了解了 Lisp 表达式的基本结构后，你可以使用函数来做更多有用的事。譬如，<code>print</code> 函数可以接受任意数量的参数，然后把它们都显示在你的终端上，<code>pprint</code> 函数还可以实现格式化打印。还有更多不同的打印函数，不过，<code>pprint</code> 在 REPL 中的效果就挺好的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[1]&gt; (pprint &quot;hello world&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;hello world&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[2]&gt;</span></span></code></pre></div><p>你可以使用 <code>defun</code> 函数来创建一个自定义函数。<code>defun</code> 函数需要你提供自定义函数的名称，以及它接受的参数列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[1]&gt; (defun myprinter (s) (pprint s))</span></span>
<span class="line"><span>MYPRINTER</span></span>
<span class="line"><span>[2]&gt; (myprinter &quot;hello world&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;hello world&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[3]&gt;</span></span></code></pre></div><h3 id="变量" tabindex="-1">变量 <a class="header-anchor" href="#变量" aria-label="Permalink to “变量”">​</a></h3><p>你可以使用 <code>setf</code> 函数来在 Lisp 中创建变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[1]&gt; (setf foo &quot;hello world&quot;)</span></span>
<span class="line"><span>&quot;hello world&quot;</span></span>
<span class="line"><span>[2]&gt; (pprint foo)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;hello world&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[3]&gt;</span></span></code></pre></div><p>你可以在表达式里嵌套表达式（就像使用某种管道一样）。举个例子，你可以先使用 <code>string-upcase</code> 函数，把某个字符串的所有字符转换成大写，然后再使用 <code>pprint</code> 函数，将它的内容格式化打印到终端上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[3]&gt; (pprint (string-upcase foo))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;HELLO WORLD&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[4]&gt;</span></span></code></pre></div><p>Lisp 是动态类型语言，这意味着，你在给变量赋值时不需要声明它的类型。Lisp 默认会把整数当作整数来处理：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[1]&gt; (setf foo 2)</span></span>
<span class="line"><span>[2]&gt; (setf bar 3)</span></span>
<span class="line"><span>[3]&gt; (+ foo bar)</span></span>
<span class="line"><span>5</span></span></code></pre></div><p>如果你想让整数被当作字符串来处理，你可以给它加上引号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[4]&gt; (setf foo &quot;2&quot;)</span></span>
<span class="line"><span>&quot;2&quot;</span></span>
<span class="line"><span>[5]&gt; (setf bar &quot;3&quot;)</span></span>
<span class="line"><span>&quot;3&quot;</span></span>
<span class="line"><span>[6]&gt; (+ foo bar)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>*** - +: &quot;2&quot; is not a number</span></span>
<span class="line"><span>The following restarts are available:</span></span>
<span class="line"><span>USE-VALUE      :R1      Input a value to be used instead.</span></span>
<span class="line"><span>ABORT          :R2      Abort main loop</span></span>
<span class="line"><span>Break 1 [7]&gt;</span></span></code></pre></div><p>在这个示例 REPL 会话中，变量 <code>foo</code> 和 <code>bar</code> 都被赋值为加了引号的数字，因此，Lisp 会把它们当作字符串来处理。数学运算符不能够用在字符串上，因此 REPL 进入了调试器模式。想要跳出这个调试器，你需要按下 <code>Ctrl+D</code> 才行（LCTT 译注：就 <code>clisp</code> 而言，使用 <code>quit</code> 关键字也可以退出）。</p><p>你可以使用 <code>typep</code> 函数对一些对象进行类型检查，它可以测试对象是否为某个特定数据类型。返回值 <code>T</code> 和 <code>NIL</code> 分别代表 <code>True</code> 和 <code>False</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[4]&gt; (typep foo &#39;string)</span></span>
<span class="line"><span>NIL</span></span>
<span class="line"><span>[5]&gt; (typep foo &#39;integer)</span></span>
<span class="line"><span>T</span></span></code></pre></div><p><code>string</code> 和 <code>integer</code> 前面加上了一个单引号（<code>&#39;</code>），这是为了防止 Lisp（错误地）把这两个单词当作是变量来求值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[6]&gt; (typep foo string)</span></span>
<span class="line"><span>*** - SYSTEM::READ-EVAL-PRINT: variable STRING has no value</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>这是一种保护某些术语（LCTT 译注：类似于字符串转义）的简便方法，正常情况下它是用 <code>quote</code> 函数来实现的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[7]&gt; (typep foo (quote string))</span></span>
<span class="line"><span>NIL</span></span>
<span class="line"><span>[5]&gt; (typep foo (quote integer))</span></span>
<span class="line"><span>T</span></span></code></pre></div><h3 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to “列表”">​</a></h3><p>不出人意料，你当然也可以在 Lisp 中创建列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[1]&gt; (setf foo (list &quot;hello&quot; &quot;world&quot;))</span></span>
<span class="line"><span>(&quot;hello&quot; &quot;world&quot;)</span></span></code></pre></div><p>你可以使用 <code>nth</code> 函数来索引列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[2]&gt; (nth 0 foo)</span></span>
<span class="line"><span>&quot;hello&quot;</span></span>
<span class="line"><span>[3]&gt; (pprint (string-capitalize (nth 1 foo)))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;World&quot;</span></span></code></pre></div><h3 id="退出-repl" tabindex="-1">退出 REPL <a class="header-anchor" href="#退出-repl" aria-label="Permalink to “退出 REPL”">​</a></h3><p>要结束一个 REPL 会话，你需要按下键盘上的 <code>Ctrl+D</code>，或者是使用 Lisp 的 <code>quit</code> 关键字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[99]&gt; (quit)</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="编写脚本" tabindex="-1">编写脚本 <a class="header-anchor" href="#编写脚本" aria-label="Permalink to “编写脚本”">​</a></h3>`,39)),e("p",null,[s[20]||(s[20]=a("Lisp 可以被编译，也可以作为解释型的脚本语言来使用。在你刚开始学习的时候，后者很可能是最容易的方式，特别是当你已经熟悉 Python 或 ",-1)),i(n,{href:"https://opensource.com/article/20/4/bash-programming-guide"},{default:p(()=>[...s[19]||(s[19]=[a("Shell 脚本",-1)])]),_:1}),s[21]||(s[21]=a(" 时。",-1))]),s[44]||(s[44]=l(`<p>下面是一个用 Common Lisp 编写的简单的“掷骰子”脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/clisp</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(defun roller (num)  </span></span>
<span class="line"><span>  (pprint (random (parse-integer (nth 0 num))))</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(setf userput *args*)</span></span>
<span class="line"><span>(setf *random-state* (make-random-state t))</span></span>
<span class="line"><span>(roller userput)</span></span></code></pre></div><p>脚本的第一行注释（LCTT 译注：称之为“<ruby>释伴<rt>shebang</rt></ruby>”）告诉了你的 POSIX 终端，该使用什么可执行文件来运行这个脚本。</p><p><code>roller</code> 函数使用 <code>defun</code> 函数创建，它在内部使用 <code>random</code> 函数来打印一个伪随机数，这个伪随机数严格小于 <code>num</code> 列表中下标为 0 的元素。在脚本中，这个 <code>num</code> 列表还没有被创建，不过没关系，因为只有当脚本被调用时，函数才会执行。</p><p>接下来的那一行，我们把运行脚本时提供的任意参数，都赋值给一个叫做 <code>userput</code> 的变量。这个 <code>userput</code> 变量是一个列表，当它被传递给 <code>roller</code> 函数后，它就会变成参数 <code>num</code>。</p><p>脚本的倒数第二行产生了一个“随机种子”。这为 Lisp 提供了足够的随机性来生成一个几乎随机的数字。</p><p>最后一行调用了自定义的 <code>roller</code> 函数，并将 <code>userput</code> 列表作为唯一的参数传递给它。</p><p>将这个文件保存为 <code>dice.lisp</code>，并赋予它可执行权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x dice.lisp</span></span></code></pre></div><p>最后，运行它，并给它提供一个数字，以作为它选择随机数的最大值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./dice.lisp 21</span></span>
<span class="line"><span></span></span>
<span class="line"><span>13</span></span>
<span class="line"><span>$ ./dice.lisp 21</span></span>
<span class="line"><span></span></span>
<span class="line"><span>7</span></span>
<span class="line"><span>$ ./dice.lisp 21</span></span>
<span class="line"><span></span></span>
<span class="line"><span>20</span></span></code></pre></div><p>看起来还不错！</p><p>你或许注意到，你的模拟骰子有可能会是 0，并且永远达不到你提供给它的最大值参数。换句话说，对于一个 20 面的骰子，这个脚本永远投不出 20（除非你把 0 当作 20）。有一个简单的解决办法，它只需要用到在本文中介绍的知识，你能够想到吗？</p><h3 id="学习-lisp" tabindex="-1">学习 Lisp <a class="header-anchor" href="#学习-lisp" aria-label="Permalink to “学习 Lisp”">​</a></h3>`,14)),e("p",null,[s[23]||(s[23]=a("无论你是想将 Lisp 作为个人脚本的实用语言，还是为了助力你的职业生涯，抑或是仅仅作为一个有趣的实验，你都可以去看看一年一度（LCTT 译注：应该是两年一度）的 ",-1)),i(n,{href:"https://itch.io/jam/spring-lisp-game-jam-2021"},{default:p(()=>[...s[22]||(s[22]=[a("Lisp ",-1),e("ruby",null,[a("游戏果酱"),e("rt",null,"Game Jam")],-1)])]),_:1}),s[24]||(s[24]=a("，从而收获一些特别有创意的用途（其中的大多数提交都是开源的，因此你可以查看代码以从中学习）。",-1))]),s[45]||(s[45]=e("p",null,"Lisp 是一门有趣而独特的语言，它有着不断增长的开发者用户群、足够悠久的历史和新兴的方言，因此，它有能力让从事各个行业的程序员都满意。",-1)),s[46]||(s[46]=e("hr",null,null,-1)),e("p",null,[s[26]||(s[26]=a("via: ",-1)),i(n,{href:"https://opensource.com/article/21/5/learn-lisp"},{default:p(()=>[...s[25]||(s[25]=[a("https://opensource.com/article/21/5/learn-lisp",-1)])]),_:1})]),e("p",null,[s[31]||(s[31]=a("作者：",-1)),i(n,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[27]||(s[27]=[a("Seth Kenlon",-1)])]),_:1}),s[32]||(s[32]=a(" 选题：",-1)),i(n,{href:"https://github.com/lkxed"},{default:p(()=>[...s[28]||(s[28]=[a("lkxed",-1)])]),_:1}),s[33]||(s[33]=a(" 译者：",-1)),i(n,{href:"https://github.com/lkxed"},{default:p(()=>[...s[29]||(s[29]=[a("lkxed",-1)])]),_:1}),s[34]||(s[34]=a(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[30]||(s[30]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[37]||(s[37]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[35]||(s[35]=[a("LCTT",-1)])]),_:1}),s[38]||(s[38]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:p(()=>[...s[36]||(s[36]=[a("Linux中国",-1)])]),_:1}),s[39]||(s[39]=a(" 荣誉推出",-1))])])}const C=t(g,[["render",h]]);export{y as __pageData,C as default};
